package me.modmuss50.mpp.platforms.github

import me.modmuss50.mpp.GithubPublishResult
import me.modmuss50.mpp.Platform
import me.modmuss50.mpp.PlatformOptions
import me.modmuss50.mpp.PlatformOptionsInternal
import me.modmuss50.mpp.PublishContext
import me.modmuss50.mpp.PublishModTask
import me.modmuss50.mpp.PublishOptions
import me.modmuss50.mpp.PublishResult
import me.modmuss50.mpp.PublishWorkAction
import me.modmuss50.mpp.PublishWorkParameters
import me.modmuss50.mpp.ReleaseType
import org.gradle.api.Task
import org.gradle.api.file.RegularFileProperty
import org.gradle.api.logging.Logger
import org.gradle.api.provider.Property
import org.gradle.api.provider.Provider
import org.gradle.api.tasks.Input
import org.gradle.api.tasks.InputFile
import org.gradle.api.tasks.Optional
import org.gradle.api.tasks.TaskProvider
import org.jetbrains.annotations.ApiStatus.Internal
import javax.inject.Inject
import kotlin.random.Random

interface GithubOptions : PlatformOptions, PlatformOptionsInternal<GithubOptions> {
    @get:InputFile
    @get:Optional
    override val file: RegularFileProperty

    /**
     * "owner/repo"
     */
    @get:Input
    val repository: Property<String>

    /**
     * Specifies the commitish value that determines where the Git tag is created from. Can be any branch or commit SHA.
     */
    @get:Input
    val commitish: Property<String>

    @get:Input
    val tagName: Property<String>

    @get:Input
    @get:Optional
    val apiEndpoint: Property<String>

    @get:Input
    val allowEmptyFiles: Property<Boolean>

    @get:InputFile
    @get:Optional
    @get:Internal
    val releaseResult: RegularFileProperty

    override fun setInternalDefaults() {
        tagName.convention(version)
        allowEmptyFiles.convention(false)
    }

    fun from(other: GithubOptions) {
        super.from(other)
        repository.convention(other.repository)
        commitish.convention(other.commitish)
        tagName.convention(other.tagName)
        apiEndpoint.convention(other.apiEndpoint)
        allowEmptyFiles.convention(other.allowEmptyFiles)
        releaseResult.convention(other.releaseResult)
    }

    fun from(other: Provider<GithubOptions>) {
        from(other.get())
    }

    fun from(other: Provider<GithubOptions>, publishOptions: Provider<PublishOptions>) {
        from(other)
        from(publishOptions.get())
    }

    /**
     * Publish to an existing release, created by another task.
     */
    fun parent(task: TaskProvider<Task>) {
        val publishTask = task.map { it as PublishModTask }
        releaseResult.set(publishTask.flatMap { it.result })

        val options = publishTask.map { it.platform as GithubOptions }
        version.set(options.flatMap { it.version })
        version.finalizeValue()
        changelog.set(options.flatMap { it.changelog })
        changelog.finalizeValue()
        type.set(options.flatMap { it.type })
        type.finalizeValue()
        displayName.set(options.flatMap { it.displayName })
        displayName.finalizeValue()
        repository.set(options.flatMap { it.repository })
        repository.finalizeValue()
        commitish.set(options.flatMap { it.commitish })
        commitish.finalizeValue()
        tagName.set(options.flatMap { it.tagName })
        tagName.finalizeValue()
    }
}

abstract class Github @Inject constructor(name: String) : Platform(name), GithubOptions {
    override fun publish(context: PublishContext) {
        val files = additionalFiles.files.toMutableList()

        if (file.isPresent) {
            files.add(file.get().asFile)
        }

        if (files.isEmpty() && !allowEmptyFiles.get()) {
            throw IllegalStateException("No files to upload to GitHub.")
        }

        context.submit(UploadWorkAction::class) {
            it.from(this)
        }
    }

    override fun dryRunPublishResult(): PublishResult {
        return GithubPublishResult(
            repository = repository.get(),
            releaseId = 0,
            url = "https://github.com/modmuss50/mod-publish-plugin/dry-run?random=${Random.nextInt(0, 1000000)}",
            title = announcementTitle.getOrElse("Download from GitHub"),
        )
    }

    override fun printDryRunInfo(logger: Logger) {
    }

    interface UploadParams : PublishWorkParameters, GithubOptions

    abstract class UploadWorkAction : PublishWorkAction<UploadParams> {
        override fun publish(): PublishResult {
            with(parameters) {
                val api = GithubApi(
                    accessToken = accessToken.get(),
                    apiEndpoint = apiEndpoint.orNull ?: "https://api.github.com",
                )

                val repo = api.getRepository(repository.get())
                val (release, created) = getOrCreateRelease(api, repo)

                val files = additionalFiles.files.toMutableList()

                if (file.isPresent) {
                    files.add(file.get().asFile)
                }

                val noneUnique = files.groupingBy { it.name }.eachCount().filter { it.value > 1 }
                if (noneUnique.isNotEmpty()) {
                    val noneUniqueNames = noneUnique.keys.joinToString(", ")
                    throw IllegalStateException("Github file names must be unique within a release, found duplicates: $noneUniqueNames")
                }

                for (file in files) {
                    api.uploadAsset(release, file)
                }

                if (created) {
                    // Publish the release after all assets are uploaded.
                    api.updateRelease(repo.fullName, release.id, GithubApi.UpdateReleaseRequest(draft = false))
                }

                return GithubPublishResult(
                    repository = repository.get(),
                    releaseId = release.id,
                    url = release.htmlUrl,
                    title = announcementTitle.getOrElse("Download from GitHub"),
                )
            }
        }

        data class ReleaseResult(val release: GithubApi.Release, val created: Boolean)

        private fun getOrCreateRelease(api: GithubApi, repo: GithubApi.Repository): ReleaseResult {
            with(parameters) {
                if (releaseResult.isPresent) {
                    val result = PublishResult.fromJson(releaseResult.get().asFile.readText()) as GithubPublishResult
                    return ReleaseResult(api.getRelease(repo.fullName, result.releaseId), false)
                }

                val release = api.createRelease(
                    repo.fullName,
                    GithubApi.CreateReleaseRequest(
                        tagName = tagName.get(),
                        targetCommitish = if (api.tagExists(repo.fullName, tagName.get())) null else commitish.get(),
                        name = displayName.get(),
                        body = changelog.get(),
                        draft = true, // Create a draft to allow uploading assets before publishing.
                        prerelease = type.get() != ReleaseType.STABLE,
                    ),
                )
                return ReleaseResult(release, true)
            }
        }
    }
}

package me.modmuss50.mpp.platforms.github

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonObject
import me.modmuss50.mpp.networking.HttpApi.get
import me.modmuss50.mpp.networking.HttpApi.patch
import me.modmuss50.mpp.networking.HttpApi.post
import me.modmuss50.mpp.networking.HttpException
import me.modmuss50.mpp.networking.RequestContext
import java.io.File
import java.net.URLEncoder
import java.net.http.HttpRequest

class GithubApi(
    private val accessToken: String,
    private val apiEndpoint: String = "https://api.github.com",
) {
    companion object {
        val httpContext = RequestContext(
            json = RequestContext.Default.json,
            userAgent = RequestContext.Default.userAgent,
            client = RequestContext.Default.client,
            exceptionFactory = RequestContext.Default.exceptionFactory,
        )
    }

    @Serializable
    data class Repository(
        @SerialName("full_name")
        val fullName: String,
    )

    @Serializable
    data class Release(
        val id: Long,
        @SerialName("html_url")
        val htmlUrl: String,
        @SerialName("upload_url")
        val uploadUrl: String,
    )

    @Serializable
    data class CreateReleaseRequest(
        @SerialName("tag_name")
        val tagName: String,
        @SerialName("target_commitish")
        val targetCommitish: String? = null,
        val name: String,
        val body: String,
        val draft: Boolean,
        val prerelease: Boolean,
    )

    @Serializable
    data class UpdateReleaseRequest(
        val draft: Boolean,
    )

    @Serializable
    class Asset

    private val headers: Map<String, String>
        get() =
            mapOf(
                "Authorization" to "token $accessToken",
                "Accept" to "application/vnd.github+json",
                "X-GitHub-Api-Version" to "2022-11-28",
            )

    // https://docs.github.com/en/rest/repos/repos?apiVersion=2022-11-28#get-a-repository
    fun getRepository(repository: String): Repository {
        val url = "$apiEndpoint/repos/$repository"
        return httpContext.get(url, headers)
    }

    // https://docs.github.com/en/rest/git/refs?apiVersion=2022-11-28#get-a-reference
    fun tagExists(repository: String, tagName: String): Boolean {
        val encodedTag = URLEncoder.encode(tagName, Charsets.UTF_8).replace("+", "%20")
        val url = "$apiEndpoint/repos/$repository/git/ref/tags/$encodedTag"
        return try {
            httpContext.get<JsonObject>(url, headers)
            true
        } catch (e: HttpException) {
            if (e.statusCode == 404) false else throw e
        }
    }

    // https://docs.github.com/en/rest/releases/releases?apiVersion=2022-11-28#create-a-release
    fun createRelease(
        repository: String,
        request: CreateReleaseRequest,
    ): Release {
        val url = "$apiEndpoint/repos/$repository/releases"
        val body = HttpRequest.BodyPublishers.ofString(httpContext.json.encodeToString(request))
        val headersWithContentType = headers + ("Content-Type" to "application/json")
        return httpContext.post(url, body, headersWithContentType)
    }

    // https://docs.github.com/en/rest/releases/releases?apiVersion=2022-11-28#get-a-release
    fun getRelease(
        repository: String,
        releaseId: Long,
    ): Release {
        val url = "$apiEndpoint/repos/$repository/releases/$releaseId"
        return httpContext.get(url, headers)
    }

    // https://docs.github.com/en/rest/releases/releases?apiVersion=2022-11-28#update-a-release
    fun updateRelease(
        repository: String,
        releaseId: Long,
        request: UpdateReleaseRequest,
    ): Release {
        val url = "$apiEndpoint/repos/$repository/releases/$releaseId"
        val body = HttpRequest.BodyPublishers.ofString(httpContext.json.encodeToString(request))
        val headersWithContentType = headers + ("Content-Type" to "application/json")
        return httpContext.patch(url, body, headersWithContentType)
    }

    // https://docs.github.com/en/rest/releases/assets?apiVersion=2022-11-28#upload-a-release-asset
    fun uploadAsset(
        release: Release,
        file: File,
    ) {
        // Parse the upload URL template and replace {?name,label} with the actual query params
        val uploadUrl = release.uploadUrl.substringBefore("{")
        val url = "$uploadUrl?name=${URLEncoder.encode(file.name, Charsets.UTF_8)}"
        val body = HttpRequest.BodyPublishers.ofFile(file.toPath())
        val headersWithContentType = headers + ("Content-Type" to "application/java-archive")
        httpContext.post<Asset>(url, body, headersWithContentType)
    }
}

